/**
 * This builds up the line item properties for use in Javascript
 *
 * @param formData {FormData} The form we will be traversing to find the properties
 *
 * @returns {Object}
 */
export function buildProperties(formData) {
  const propertyKeyValues = [...formData.entries()].filter(([key, value]) => key.includes('properties[') && value !== '');

  function propertyReducer(properties, [key, value]) {
    const strippedKey = key.replace('properties[', '').slice(0, -1);
    return { ...properties,
      [strippedKey]: value
    };
  }

  return propertyKeyValues.reduce(propertyReducer, {});
}